    def __init__(self):
        self.permissions = {
            'viewer': {'read': True},
            'editor': {'read': True, 'write': True}
        }

    def allowed(self, role, action):
        # Check if the role exists in the permissions dictionary
        if role in self.permissions:
            # Check if the action is allowed for the role
            return self.permissions[role].get(action, False)
        else:
            # If the role is not recognized, deny the action
            return False

    def roles_for(self, action):
        # Collect all roles that are allowed to perform the given action
        roles = []
        for role, actions in self.permissions.items():
            if actions.get(action, False):
                roles.append(role)
        # Return a sorted detached list
        return sorted(roles)

