            return round(amount, 2)
        elif plan == 'pro':
            discounted_amount = amount * PriceEngine.DISCOUNT_PRO
            return round(discounted_amount, 2)
        else:
            raise KeyError(f"Unknown plan: {plan}")

    @staticmethod
    def discounts():
        """
        Returns a detached dictionary mapping each supported plan to its fractional discount.

        :return: dict, mapping plan names to their discount factors
        """
        return {
            'basic': 1.0,
            'pro': PriceEngine.DISCOUNT_PRO
        }
